// 持久化的 locale 只接受已知值；被篡改/旧版本残留的非法值回退到默认 'en'，
// 避免把任意字符串写进 <html lang> 造成浏览器语言识别与文案脱节。
const storedLocale = globalThis.localStorage?.getItem('panel.locale');
const state = reactive({ locale: (storedLocale === 'zh-CN' || storedLocale === 'en' ? storedLocale : 'en') as Locale });

function applyDocumentLang(locale: Locale) {
  // Keep <html lang> in sync with the active UI language. Browsers (Chrome
  // translate prompt), screen readers and search engines read this attribute;
  // without it the page keeps reporting the static index.html default (en)
  // even after the user switches to Chinese.
  if (typeof document !== 'undefined') document.documentElement.lang = locale;
}

applyDocumentLang(state.locale);

export function useI18n() {
  const locale = computed(() => state.locale);

  function setLocale(next: Locale) {
    const value: Locale = next === 'zh-CN' || next === 'en' ? next : 'en';
    state.locale = value;
    globalThis.localStorage?.setItem('panel.locale', value);
    applyDocumentLang(value);
  }

  function t(key: string, params?: Record<string, string | number>) {
    let text = messages[state.locale][key] || messages.en[key] || key;
    if (params) {
      Object.entries(params).forEach(([name, value]) => {
        text = text.split(`{${name}}`).join(String(value));
      });
    }
    return text;
  }

  return { locale, setLocale, t };
}

export function translateRuntimeEventType(t: (key: string, params?: Record<string, string | number>) => string, value: string) {
  const key = `runtimeEventTypes.${value}`;
  const label = t(key);
  return label === key ? value : label;
}

